UPDATE olympiads SET
    title = 'Олимпиада по программированию — отборочный тур',
    description = 'Отборочный этап для студентов 1–3 курсов. Задачи на базовые конструкции языка, HTTP и алгоритмическое мышление. Во время попытки включён прокторинг: камера, полноэкранный режим и контроль вкладок.',
    start_time = NOW() - INTERVAL '1 day',
    end_time = NOW() + INTERVAL '365 days',
    duration_minutes = 60
WHERE id = '11111111-1111-1111-1111-111111111111';

UPDATE questions SET text = 'Чему равно значение выражения 2 + 2 * 2 в большинстве языков программирования?',
    options = '["8","6","4","Ошибка компиляции"]', correct_answer = '6'
WHERE id = '22222222-2222-2222-2222-222222222201';
UPDATE questions SET text = 'Какие из перечисленных типов в Java являются примитивными целочисленными?',
    options = '["int","Integer","long","String"]', correct_answer = 'int,long'
WHERE id = '22222222-2222-2222-2222-222222222202';
UPDATE questions SET text = 'Какой HTTP-метод обычно используют для создания нового ресурса в REST API?'
WHERE id = '22222222-2222-2222-2222-222222222203';
UPDATE questions SET text = 'Опишите алгоритм проверки, является ли строка палиндромом. Оцените его сложность по времени и памяти. Можно приложить схему или фото решения.'
WHERE id = '22222222-2222-2222-2222-222222222204';

