INSERT INTO questions (id, olympiad_id, text, type, options, correct_answer, points) VALUES
    ('44444444-4444-4444-4444-444444444401', '33333333-3333-3333-3333-333333333301', 'Какова средняя временная сложность быстрой сортировки?', 'SINGLE_CHOICE', '["O(n)", "O(n log n)", "O(n²)", "O(log n)"]', 'O(n log n)', 5),
    ('44444444-4444-4444-4444-444444444402', '33333333-3333-3333-3333-333333333301', 'Какие структуры данных работают по принципу LIFO?', 'MULTIPLE_CHOICE', '["Стек", "Очередь", "Стек вызовов", "Дек в режиме очереди"]', 'Стек,Стек вызовов', 10),
    ('44444444-4444-4444-4444-444444444403', '33333333-3333-3333-3333-333333333301', 'Какой алгоритм находит кратчайшие пути от одной вершины во взвешенном графе без отрицательных рёбер? (одно слово, фамилия автора)', 'TEXT', NULL, 'Дейкстра', 10),
    ('44444444-4444-4444-4444-444444444404', '33333333-3333-3333-3333-333333333301', 'Сколько рёбер в дереве из 10 вершин?', 'SINGLE_CHOICE', '["9", "10", "11", "Зависит от формы дерева"]', '9', 5),
    ('44444444-4444-4444-4444-444444444405', '33333333-3333-3333-3333-333333333301', 'Объясните, почему поиск в хеш-таблице в среднем работает за O(1), и когда это нарушается.', 'MANUAL_REVIEW', NULL, NULL, 10)
