INSERT INTO answers (id, participation_id, question_id, answer, is_correct, points_earned, review_comment, submitted_at) VALUES
    ('66666666-6666-6666-0001-444444444401', '55555555-5555-5555-5555-555555555501', '44444444-4444-4444-4444-444444444401', 'O(n log n)', TRUE, 5, NULL, NOW() - INTERVAL '57588 minutes'),
    ('66666666-6666-6666-0001-444444444402', '55555555-5555-5555-5555-555555555501', '44444444-4444-4444-4444-444444444402', 'Стек|Стек вызовов', TRUE, 10, NULL, NOW() - INTERVAL '57572 minutes'),
    ('66666666-6666-6666-0001-444444444403', '55555555-5555-5555-5555-555555555501', '44444444-4444-4444-4444-444444444403', 'Дейкстра', TRUE, 10, NULL, NOW() - INTERVAL '57594 minutes'),
    ('66666666-6666-6666-0001-444444444404', '55555555-5555-5555-5555-555555555501', '44444444-4444-4444-4444-444444444404', '9', TRUE, 5, NULL, NOW() - INTERVAL '57593 minutes'),
    ('66666666-6666-6666-0001-444444444405', '55555555-5555-5555-5555-555555555501', '44444444-4444-4444-4444-444444444405', 'Хеш-функция сразу даёт индекс корзины, поэтому доступ в среднем O(1). При плохой хеш-функции или большом числе коллизий цепочки растут и поиск деградирует до O(n); поэтому таблицу рехешируют при превышении коэффициента заполнения.', TRUE, 10, 'Отличное объяснение: коллизии, коэффициент заполнения и рехеширование.', NOW() - INTERVAL '57568 minutes'),
    ('66666666-6666-6666-0002-444444444401', '55555555-5555-5555-5555-555555555502', '44444444-4444-4444-4444-444444444401', 'O(n log n)', TRUE, 5, NULL, NOW() - INTERVAL '57454 minutes'),
    ('66666666-6666-6666-0002-444444444402', '55555555-5555-5555-5555-555555555502', '44444444-4444-4444-4444-444444444402', 'Стек|Стек вызовов', TRUE, 10, NULL, NOW() - INTERVAL '57437 minutes'),
    ('66666666-6666-6666-0002-444444444403', '55555555-5555-5555-5555-555555555502', '44444444-4444-4444-4444-444444444403', 'Флойд', FALSE, 0, NULL, NOW() - INTERVAL '57423 minutes'),
    ('66666666-6666-6666-0002-444444444404', '55555555-5555-5555-5555-555555555502', '44444444-4444-4444-4444-444444444404', '9', TRUE, 5, NULL, NOW() - INTERVAL '57457 minutes'),
    ('66666666-6666-6666-0002-444444444405', '55555555-5555-5555-5555-555555555502', '44444444-4444-4444-4444-444444444405', 'Индекс считается по хешу ключа, поэтому идём прямо в нужную ячейку массива. Нарушается, когда много ключей попадает в одну корзину и приходится перебирать цепочку целиком, в худшем случае O(n).', TRUE, 10, 'Полный и точный ответ.', NOW() - INTERVAL '57424 minutes'),
    ('66666666-6666-6666-0003-444444444401', '55555555-5555-5555-5555-555555555503', '44444444-4444-4444-4444-444444444401', 'O(n log n)', TRUE, 5, NULL, NOW() - INTERVAL '57310 minutes'),
    ('66666666-6666-6666-0003-444444444402', '55555555-5555-5555-5555-555555555503', '44444444-4444-4444-4444-444444444402', 'Стек|Очередь', FALSE, 0, NULL, NOW() - INTERVAL '57321 minutes'),
    ('66666666-6666-6666-0003-444444444403', '55555555-5555-5555-5555-555555555503', '44444444-4444-4444-4444-444444444403', 'Дейкстра', TRUE, 10, NULL, NOW() - INTERVAL '57318 minutes'),
    ('66666666-6666-6666-0003-444444444404', '55555555-5555-5555-5555-555555555503', '44444444-4444-4444-4444-444444444404', '9', TRUE, 5, NULL, NOW() - INTERVAL '57296 minutes'),
    ('66666666-6666-6666-0003-444444444405', '55555555-5555-5555-5555-555555555503', '44444444-4444-4444-4444-444444444405', 'Ключ превращается в номер ячейки, перебора нет. Если таблица переполнена, коллизий становится больше и поиск замедляется.', FALSE, 6, 'Верно в целом, но не сказано, до какой сложности деградирует поиск.', NOW() - INTERVAL '57288 minutes'),
    ('66666666-6666-6666-0004-444444444401', '55555555-5555-5555-5555-555555555504', '44444444-4444-4444-4444-444444444401', 'O(n log n)', TRUE, 5, NULL, NOW() - INTERVAL '57182 minutes'),
    ('66666666-6666-6666-0004-444444444402', '55555555-5555-5555-5555-555555555504', '44444444-4444-4444-4444-444444444402', 'Стек|Стек вызовов', TRUE, 10, NULL, NOW() - INTERVAL '57171 minutes'),
    ('66666666-6666-6666-0004-444444444403', '55555555-5555-5555-5555-555555555504', '44444444-4444-4444-4444-444444444403', 'Дейкстра', TRUE, 10, NULL, NOW() - INTERVAL '57181 minutes'),
    ('66666666-6666-6666-0004-444444444404', '55555555-5555-5555-5555-555555555504', '44444444-4444-4444-4444-444444444404', '10', FALSE, 0, NULL, NOW() - INTERVAL '57159 minutes'),
    ('66666666-6666-6666-0004-444444444405', '55555555-5555-5555-5555-555555555504', '44444444-4444-4444-4444-444444444405', 'Хеш-таблица хранит пары ключ-значение в массиве, позиция вычисляется хеш-функцией за константу. При коллизиях используется метод цепочек или открытая адресация, и время растёт вместе с длиной цепочки.', NULL, NULL, NULL, NOW() - INTERVAL '57154 minutes'),
    ('66666666-6666-6666-0005-444444444401', '55555555-5555-5555-5555-555555555505', '44444444-4444-4444-4444-444444444401', 'O(n²)', FALSE, 0, NULL, NOW() - INTERVAL '57031 minutes'),
    ('66666666-6666-6666-0005-444444444402', '55555555-5555-5555-5555-555555555505', '44444444-4444-4444-4444-444444444402', 'Стек|Стек вызовов', TRUE, 10, NULL, NOW() - INTERVAL '57046 minutes'),
    ('66666666-6666-6666-0005-444444444403', '55555555-5555-5555-5555-555555555505', '44444444-4444-4444-4444-444444444403', 'Дейкстра', TRUE, 10, NULL, NOW() - INTERVAL '57042 minutes'),
    ('66666666-6666-6666-0005-444444444404', '55555555-5555-5555-5555-555555555505', '44444444-4444-4444-4444-444444444404', '9', TRUE, 5, NULL, NOW() - INTERVAL '57029 minutes'),
    ('66666666-6666-6666-0005-444444444405', '55555555-5555-5555-5555-555555555505', '44444444-4444-4444-4444-444444444405', 'Позиция элемента вычисляется по ключу, поэтому O(1). Медленнее становится при коллизиях.', FALSE, 5, 'Идея верная, но объяснение слишком краткое: нет причин коллизий и оценки худшего случая.', NOW() - INTERVAL '57029 minutes'),
    ('66666666-6666-6666-0006-444444444401', '55555555-5555-5555-5555-555555555506', '44444444-4444-4444-4444-444444444401', 'O(n log n)', TRUE, 5, NULL, NOW() - INTERVAL '56875 minutes'),
    ('66666666-6666-6666-0006-444444444402', '55555555-5555-5555-5555-555555555506', '44444444-4444-4444-4444-444444444402', 'Стек|Очередь', FALSE, 0, NULL, NOW() - INTERVAL '56909 minutes'),
    ('66666666-6666-6666-0006-444444444403', '55555555-5555-5555-5555-555555555506', '44444444-4444-4444-4444-444444444403', 'Флойд', FALSE, 0, NULL, NOW() - INTERVAL '56876 minutes'),
    ('66666666-6666-6666-0006-444444444404', '55555555-5555-5555-5555-555555555506', '44444444-4444-4444-4444-444444444404', '9', TRUE, 5, NULL, NOW() - INTERVAL '56875 minutes'),
    ('66666666-6666-6666-0006-444444444405', '55555555-5555-5555-5555-555555555506', '44444444-4444-4444-4444-444444444405', 'Потому что используется массив.', FALSE, 2, 'Ответ слишком общий: не объяснено, как ключ превращается в индекс.', NOW() - INTERVAL '56873 minutes'),
    ('66666666-6666-6666-0007-444444444401', '55555555-5555-5555-5555-555555555507', '44444444-4444-4444-4444-444444444401', 'O(n²)', FALSE, 0, NULL, NOW() - INTERVAL '56772 minutes'),
    ('66666666-6666-6666-0007-444444444402', '55555555-5555-5555-5555-555555555507', '44444444-4444-4444-4444-444444444402', 'Стек|Очередь', FALSE, 0, NULL, NOW() - INTERVAL '56761 minutes'),
    ('66666666-6666-6666-0007-444444444403', '55555555-5555-5555-5555-555555555507', '44444444-4444-4444-4444-444444444403', 'Дейкстра', TRUE, 10, NULL, NOW() - INTERVAL '56773 minutes'),
    ('66666666-6666-6666-0007-444444444404', '55555555-5555-5555-5555-555555555507', '44444444-4444-4444-4444-444444444404', '9', TRUE, 5, NULL, NOW() - INTERVAL '56767 minutes'),
    ('66666666-6666-6666-0007-444444444405', '55555555-5555-5555-5555-555555555507', '44444444-4444-4444-4444-444444444405', 'Хеш считается за O(1) и по нему берётся элемент массива. Если хеш-функция плохая, все ключи окажутся в одной корзине и поиск станет линейным.', FALSE, 7, 'Хорошо: указан худший случай и его причина.', NOW() - INTERVAL '56744 minutes'),
    ('66666666-6666-6666-0008-444444444401', '55555555-5555-5555-5555-555555555508', '44444444-4444-4444-4444-444444444401', 'O(n log n)', TRUE, 5, NULL, NOW() - INTERVAL '56625 minutes'),
    ('66666666-6666-6666-0008-444444444402', '55555555-5555-5555-5555-555555555508', '44444444-4444-4444-4444-444444444402', 'Стек|Стек вызовов', TRUE, 10, NULL, NOW() - INTERVAL '56634 minutes'),
    ('66666666-6666-6666-0008-444444444403', '55555555-5555-5555-5555-555555555508', '44444444-4444-4444-4444-444444444403', 'Дейкстра', TRUE, 10, NULL, NOW() - INTERVAL '56621 minutes'),
    ('66666666-6666-6666-0008-444444444404', '55555555-5555-5555-5555-555555555508', '44444444-4444-4444-4444-444444444404', '9', TRUE, 5, NULL, NOW() - INTERVAL '56635 minutes'),
    ('66666666-6666-6666-0008-444444444405', '55555555-5555-5555-5555-555555555508', '44444444-4444-4444-4444-444444444405', 'Доступ по индексу массива — O(1), индекс даёт хеш-функция. Проблемы начинаются при коллизиях и при росте таблицы, когда нужно перестроение: отдельная вставка может стоить O(n), но амортизированно остаётся O(1).', TRUE, 10, 'Отличный ответ, учтено амортизированное время.', NOW() - INTERVAL '56610 minutes'),
    ('66666666-6666-6666-0009-444444444401', '55555555-5555-5555-5555-555555555509', '44444444-4444-4444-4444-444444444401', 'O(n²)', FALSE, 0, NULL, NOW() - INTERVAL '56482 minutes'),
    ('66666666-6666-6666-0009-444444444402', '55555555-5555-5555-5555-555555555509', '44444444-4444-4444-4444-444444444402', 'Стек|Очередь', FALSE, 0, NULL, NOW() - INTERVAL '56466 minutes'),
    ('66666666-6666-6666-0009-444444444403', '55555555-5555-5555-5555-555555555509', '44444444-4444-4444-4444-444444444403', 'Флойд', FALSE, 0, NULL, NOW() - INTERVAL '56490 minutes'),
    ('66666666-6666-6666-0009-444444444404', '55555555-5555-5555-5555-555555555509', '44444444-4444-4444-4444-444444444404', '9', TRUE, 5, NULL, NOW() - INTERVAL '56495 minutes'),
    ('66666666-6666-6666-0009-444444444405', '55555555-5555-5555-5555-555555555509', '44444444-4444-4444-4444-444444444405', 'Не знаю точно, наверное из-за хеша.', FALSE, 1, 'Ответ не раскрывает вопрос.', NOW() - INTERVAL '56464 minutes')
